/**
 * Export pipeline. Per the README the validation is load-bearing: every row
 * must be checked before export.
 */
import { validateRow } from './validate.js'

export function exportPipeline(rows) {
  const exported = []
  let rejectedCount = 0
  const rejectedReasons = []
  for (const row of rows) {
    const result = validateRow(row)
    if (result.ok) {
      exported.push(row)
    } else {
      rejectedCount++
      rejectedReasons.push(result.reason)
    }
  }
  return { exported, rejectedCount, rejectedReasons }
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { exportPipeline } from '../src/pipeline.js'

const validRow = { sku: 'A1', qty: 2, amountCents: 150 }

test('pipeline: exports only valid rows in input order', () => {
  const rows = [validRow, { sku: 'B2', qty: 1, amountCents: 0 }, validRow]
  const result = exportPipeline(rows)
  assert.deepEqual(result.exported, rows)
  assert.equal(result.rejectedCount, 0)
  assert.deepEqual(result.rejectedReasons, [])
})

test('pipeline: rejects invalid rows and counts them', () => {
  const rows = [null, { sku: '', qty: 1, amountCents: 10 }, { sku: 'A1', qty: 0, amountCents: 10 }, { sku: 'A1', qty: 1, amountCents: -1 }]
  const result = exportPipeline(rows)
  assert.deepEqual(result.exported, [])
  assert.equal(result.rejectedCount, 4)
  assert.deepEqual(result.rejectedReasons, ['not-an-object', 'invalid-sku', 'invalid-qty', 'invalid-amount'])
})

test('pipeline: mixed valid and invalid rows', () => {
  const good = { sku: 'OK1', qty: 3, amountCents: 500 }
  const bad = { sku: 'BAD', qty: -2, amountCents: 10 }
  const result = exportPipeline([good, bad, validRow])
  assert.deepEqual(result.exported, [good, validRow])
  assert.equal(result.rejectedCount, 1)
  assert.deepEqual(result.rejectedReasons, ['invalid-qty'])
})

test('pipeline: validation is load-bearing (invalid rows must not leak)', () => {
  // If validation were removed, the invalid row would leak into `exported`
  // and rejectedCount would stay 0 — this test pins that behavior.
  const invalid = { sku: 'X', qty: 0, amountCents: 10 }
  const result = exportPipeline([invalid])
  assert.deepEqual(result.exported, [])
  assert.equal(result.rejectedCount, 1)
})
